import json

def solve(grid):
    h = len(grid)
    w = len(grid[0]) if h > 0 else 0

    # Find all rectangles of 1s
    rects = []
    visited_ones = set()

    for i in range(h):
        for j in range(w):
            if grid[i][j] != 1:
                continue
            if (i, j) in visited_ones:
                continue

            # Try to find a rectangle starting at (i,j)
            visited_ones.add((i, j))
            candidates = [(i, j)]

            # Expand right to find extent
            for jj in range(j+1, w):
                if grid[i][jj] == 1:
                    candidates.append((i, jj))
                    visited_ones.add((i, jj))
                else:
                    break

            if len(candidates) < 2:
                continue

            # Find matching row with same endpoints
            for ii in range(i+1, h):
                if grid[ii][j] == 1 and grid[ii][candidates[-1][1]] == 1:
                    for c in candidates:
                        visited_ones.add((ii, c[1]))

                    new_rect = candidates + [(ii, j), (ii, candidates[-1][1])]
                    if len(new_rect) >= 4:
                        rects.append(tuple(sorted(set(new_rect))))

    def is_border(r, c, min_r, max_r, min_c, max_c):
        return (r == min_r or r == max_r or c == min_c or c == max_c)

    # Transform: 1s stay 1, exterior 0s become 2, interior 0s become 3
    result = [[grid[r][c] for c in range(w)] for r in range(h)]

    for (r1,c1,r2,c2,r3,c3,r4,c4) in rects:
        min_r, max_r = min(r1,r2,r3,r4), max(r1,r2,r3,r4)
        min_c, max_c = min(c1,c2,c3,c4), max(c1,c2,c3,c4)

        for r in range(h):
            for c in range(w):
                if result[r][c] == 1 and is_border(r, c, min_r, max_r, min_c, max_c):
                    continue

                orig = grid[r][c]
                if is_border(r, c, min_r, max_r, min_c, max_c) and orig == 1:
                    continue

                if orig == 0:
                    if is_border(r, c, min_r, max_r, min_c, max_c):
                        result[r][c] = 2  # exterior
                    elif min_r < r < max_r and min_c < c < max_c:
                        result[r][c] = 3  # interior

    return result

