# New idea: What if we use DIFFERENT flood-fill logic?
# Flood fill from edges, but stop when you hit a row or column that contains any 1?

def solve_v3(grid):
    h, w = len(grid), len(grid[0])

    # Mark rows and cols with 1s
    rows_with_1 = {r for r in range(h) for c in range(w) if grid[r][c] == 1}
    cols_with_1 = {c for r in range(h) for c in range(w) if grid[r][c] == 1}

    print(f"Rows with 1: {sorted(rows_with_1)}")
    print(f"Cols with 1: {sorted(cols_with_1)}")

    visited_exterior = set()
    queue = []

    # Add corner/edge cells that are 0 to queue
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and (r == 0 or r == h-1 or c == 0 or c == w-1):
                queue.append((r,c))
                visited_exterior.add((r,c))

    while queue:
        r, c = queue.pop(0)
        for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
            nr, nc = r+dr, c+dc
            if 0 <= nr < h and 0 <= nc < w:
                if grid[nr][nc] == 0 and (nr,nc) not in visited_exterior:
                    # Check if entering a "forbidden" row/col
                    if nr in rows_with_1 or nc in cols_with_1:
                        continue
                    visited_exterior.add((nr,nc))
                    queue.append((nr,nc))

    print(f"\nExterior reachable: {len(visited_exterior)} cells")

    result = [[grid[r][c] for c in range(w)] for r in range(h)]

    for r in range(h):
        for c in range(w):
            orig = grid[r][c]
            if orig == 1:
                continue

            if (r,c) in visited_exterior:
                result[r][c] = 2
            else:
                # Not exterior - now determine if it's interior
                # Check bbox of 1s
                ones = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 1]
                min_r, max_r = min(r for r,c in ones), max(r for r,c in ones)
                min_c, max_c = min(c for r,c in ones), max(c for r,c in ones)

                if min_r < r < max_r and min_c < c < max_c:
                    result[r][c] = 3

    return result

