import json

# Define the solve function based on our derivation
def solve(grid):
    h = len(grid)
    w = len(grid[0]) if h > 0 else 0

    # Find all connected components of 1s using BFS
    visited = set()
    components = []

    for i in range(h):
        for j in range(w):
            if grid[i][j] != 1:
                continue
            if (i,j) in visited:
                continue

            # BFS to find all orthogonally connected 1s
            component = []
            queue = [(i,j)]
            visited.add((i,j))

            while queue:
                r, c = queue.pop(0)
                component.append((r,c))

                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = r+dr, c+dc
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1 and (nr,nc) not in visited:
                        visited.add((nr,nc))
                        queue.append((nr,nc))

            # Get bounding box
            min_r = min(r for r,c in component)
            max_r = max(r for r,c in component)
            min_c = min(c for r,c in component)
            max_c = max(c for r,c in component)

            components.append((min_r, max_r, min_c, max_c))

    def is_border(r, c, min_r, max_r, min_c, max_c):
        return (r == min_r or r == max_r or c == min_c or c == max_c)

    # Create result as copy of input
    result = [[grid[r][c] for c in range(w)] for r in range(h)]

    # Apply transformations for each component
    for (min_r, max_r, min_c, max_c) in components:
        for r in range(h):
            for c in range(w):
                orig = grid[r][c]
                if orig == 1:
                    # Keep 1s that are on border
                    if is_border(r, c, min_r, max_r, min_c, max_c):
                        continue
                elif orig == 0:
                    # Exterior 0 -> 2
                    if is_border(r, c, min_r, max_r, min_c, max_c):
                        result[r][c] = 2
                    # Interior 0 -> 3
                    elif min_r < r < max_r and min_c < c < max_c:
                        result[r][c] = 3

    return result

