def flood_from_boundary_8(grid):
    """Flood fill from all boundary cells using 8-connectivity"""
    rows = len(grid)
    cols = len(grid[0])

    visited = [[False]*cols for _ in range(rows)]

    # Queue for BFS - start with all boundary cells that are 0
    queue = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0:
                # Boundary cell (row 0, row max, col 0, or col max)
                if r == 0 or r == rows-1 or c == 0 or c == cols-1:
                    queue.append((r, c))
                    visited[r][c] = True

    # BFS with 8 neighbors
    queue_idx = 0
    while queue_idx < len(queue):
        r, c = queue[queue_idx]
        queue_idx += 1

        # 8 neighbors: including diagonals
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue

                nr, nc = r + dr, c + dc

                if 0 <= nr < rows and 0 <= nc < cols:
                    if grid[nr][nc] == 0 and not visited[nr][nc]:
                        visited[nr][nc] = True
                        queue.append((nr, nc))

    # Find interior cells (0s not reachable from boundary)
    interior_cells = []
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 0 and not visited[r][c]:
                interior_cells.append((r, c))

    return visited, interior_cells

