from collections import deque

def solve_arc(grid_in):
    """
    Final ARC rule:
    1. Find bbox of 1-component
    2. Check if structure is OPEN (any bbox zero can reach outside via 0s) or CLOSED
    3. IF OPEN: Apply transformation
       - Flood-fill exterior 0s from grid boundary (8-connectivity)
       - Interior cells become 3 (enclosed within U-shape)
       - Exterior cells touching bbox become 2
       - Exterior cells not touching bbox stay 0
       - Exception: Cells with no 1s in 3x3 neighborhood stay 0
    4. IF CLOSED: Return identity (grid unchanged)
    """
    rows, cols = len(grid_in), len(grid_in[0])

    # Step 1: Find bbox of 1s
    min_r, max_r, min_c, max_c = rows, 0, cols, 0
    for r in range(rows):
        for c in range(cols):
            if grid_in[r][c] == 1:
                min_r = min(min_r, r)
                max_r = max(max_r, r)
                min_c = min(min_c, c)
                max_c = max(max_c, c)

    # Step 2: Check if open/closed
    def can_reach_outside(r, c):
        queue = deque([(r, c)])
        visited = {(r, c)}

        while queue:
            cr, cc = queue.popleft()

            if cr < min_r or cr > max_r or cc < min_c or cc > max_c:
                return True

            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if grid_in[nr][nc] == 0 and (nr, nc) not in visited:
                            visited.add((nr, nc))
                            queue.append((nr, nc))
        return False

    bbox_zeros = set()
    for r in range(min_r, max_r + 1):
        for c in range(min_c, max_c + 1):
            if grid_in[r][c] == 0:
                bbox_zeros.add((r, c))

    is_open = False
    for r, c in bbox_zeros:
        if can_reach_outside(r, c):
            is_open = True
            break

    print(f"Structure is {'OPEN' if is_open else 'CLOSED'}")

    if not is_open:
        # Identity - return copy of input
        return [row[:] for row in grid_in], "identity"

    # Step 3: Transformation (structure is open)
    # Flood-fill exterior 0s via 8-connectivity from grid boundary
    visited_exterior_8 = [[False]*cols for _ in range(rows)]
    q = deque()

    for r in range(rows):
        for c in range(cols):
            if grid_in[r][c] == 0 and (r == 0 or r == rows-1 or c == 0 or c == cols-1):
                visited_exterior_8[r][c] = True
                q.append((r, c))

    while q:
        r, c = q.popleft()
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    if not visited_exterior_8[nr][nc] and grid_in[nr][nc] == 0:
                        visited_exterior_8[nr][nc] = True
                        q.append((nr, nc))

    result = []
    for r in range(rows):
        row_out = []
        for c in range(cols):
            val = grid_in[r][c]
            if val == 1:
                row_out.append(1)
            else:
                # Check exception: any 1 in 3x3?
                has_one_in_3x3 = False
                for dr in [-1, 0, 1]:
                    for dc in [-1, 0, 1]:
                        if dr == 0 and dc == 0:
                            continue
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid_in[nr][nc] == 1:
                                has_one_in_3x3 = True
                                break
                    if has_one_in_3x3:
                        break

                if not has_one_in_3x3:
                    row_out.append(0)  # Exception
                elif visited_exterior_8[r][c]:
                    # Exterior cell
                    # Touching bbox boundary?
                    touches_bbox = False
                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = r + dr, c + dc
                            if 0 <= nr < rows and 0 <= nc < cols:
                                if grid_in[nr][nc] == 1:
                                    touches_bbox = True
                                    break
                        if touches_bbox:
                            break

                    if touches_bbox:
                        row_out.append(2)
                    else:
                        row_out.append(0)
                else:
                    # Interior cell (within bbox, unreachable from grid boundary)
                    row_out.append(3)

        result.append(row_out)

    return result, "transformed"

