import os, glob, re

def load():
    d = os.environ.get('RLM_SESSION_DIR', '/tmp')
    sessions_path = os.path.join(d, 'sessions')
    if not os.path.exists(sessions_path):
        return {}

    for f in sorted(glob.glob(os.path.join(sessions_path, '*.jsonl'))):
        with open(f) as fp:
            text = fp.read().replace('\\n', '\n')
        G = {}
        pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n'
        matches = list(re.finditer(pattern, text))

        for m in matches:
            k, h, w = m.group(1), int(m.group(2)), int(m.group(3))
            # Extract next h lines that look like grid rows
            remaining = text[m.end():m.end()+h*80]  # Approximate line length
            rows = [r.split() for r in remaining.split('\n')[:h]]
            if len(rows) == h and all(len(r) == w for r in rows) and all(all(x.isdigit() for x in r) for r in rows):
                G[k] = [[int(x) for x in r] for r in rows]

        if G:
            print(f"Loaded from {f}: {list(G.keys())}")
            return G

    return {}

